import logger from '@salesforce/retail-react-app/app/utils/logger-instance';

// constant
import {
  API_ERROR_MESSAGE,
  EINSTEIN_RECOMMENDERS,
  MAX_CACHE_AGE,
  TOAST_ACTION_VIEW_WISHLIST,
  TOAST_MESSAGE_ADDED_TO_WISHLIST,
  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
  STALE_WHILE_REVALIDATE,
} from '@salesforce/retail-react-app/app/constants';
import { rebuildPathWithParams, productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import { useHistory, useLocation, useParams } from 'react-router-dom';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';

/*
 * `@salesforce/retail-react-app` ships no TypeScript types (see
 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
 * subpaths), so the product / variant / category values this page threads between base
 * hooks and base components have no compile-time shape *from that package*. But the shapes
 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
 * Definitions rule says to import those directly. Deferred to a follow-up only because the
 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
 */
type SfccProduct = any;
type SfccVariant = any;
type SfccCategory = any;

